import type { BankQuestion } from "@/lib/bank";

/** Financial & Cost Accounting (Management & Commerce): 90 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-accounting-1","question":"A trader starts business with cash ₹5,00,000, buys goods for ₹1,20,000 on credit and sells goods costing ₹40,000 for ₹55,000 in cash. What are the total assets after these transactions?","options":["₹6,20,000","₹6,35,000","₹6,75,000","₹5,15,000"],"answer":1,"explanation":"Cash = 5,00,000 + 55,000 = ₹5,55,000; stock = 1,20,000 − 40,000 = ₹80,000. Total assets = ₹6,35,000 (= creditors 1,20,000 + capital 5,15,000, the capital including the ₹15,000 profit). ₹6,20,000 ignores the profit and ₹6,75,000 forgets to reduce the stock sold.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-2","question":"Which of these errors will NOT cause the trial balance to disagree?","options":["The sales book is overcast by ₹2,000","A debit of ₹500 is posted to the credit side of a supplier's account","Machinery bought for ₹50,000 is debited to the Purchases account","A sales invoice of ₹3,000 is posted to the Sales account but not to the customer's account"],"answer":2,"explanation":"Debiting machinery to Purchases is an error of principle: the debit is still a debit of the right amount, so the totals agree. The other three are one-sided errors that change only one side of the trial balance.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-3","question":"After a suspense account has been opened, it is found that the sales book was undercast by ₹2,000. What is the rectifying entry?","options":["Sales A/c Dr ₹2,000 To Suspense A/c ₹2,000","Debtors A/c Dr ₹2,000 To Sales A/c ₹2,000","Suspense A/c Dr ₹2,000 To Sales A/c ₹2,000","No entry is needed because the debtors were posted correctly"],"answer":2,"explanation":"Undercasting the sales book means the Sales account was credited ₹2,000 too little, while the individual debtors were debited correctly. Only the Sales account needs a further credit, and the other side goes to Suspense: Suspense Dr, Sales Cr.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-4","question":"A trial balance does not agree and the difference is put in a suspense account. The only errors are: (a) the purchase returns book was overcast by ₹1,000; (b) salary of ₹2,500 was posted to the Salary account as ₹5,200; (c) discount allowed of ₹400 was not posted to the Discount account. What was the suspense account balance?","options":["₹1,300 debit","₹4,100 credit","₹3,300 debit","₹1,300 credit"],"answer":3,"explanation":"(a) Credit side too high by ₹1,000. (b) Debit side too high by ₹2,700. (c) Debit side too low by ₹400. Net: debits exceed credits by 2,700 − 400 − 1,000 = ₹1,300, so the suspense account needed a credit of ₹1,300 to make the totals agree.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-5","question":"A machine is bought on 1 July 2022 for ₹4,80,000 and ₹20,000 is spent on installing it. Residual value is ₹50,000 and useful life 9 years. With the financial year ending 31 March and straight-line depreciation, what is the charge for 2022-23?","options":["₹37,500","₹50,000","₹41,667","₹35,833"],"answer":0,"explanation":"Cost = 4,80,000 + 20,000 = ₹5,00,000 (installation is capitalised). Annual charge = (5,00,000 − 50,000) ÷ 9 = ₹50,000. For 9 months (July to March): 50,000 × 9/12 = ₹37,500. ₹35,833 leaves out installation; ₹50,000 ignores time.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-6","question":"An asset bought on 1 April 2021 for ₹8,00,000 is depreciated at 20% a year on the written-down value. It is sold on 30 September 2023 for ₹4,50,000. What is the profit or loss on sale (year ends 31 March)?","options":["Loss ₹62,000","Profit ₹40,400","Loss ₹10,800","Profit ₹10,800"],"answer":2,"explanation":"Book value on 31 Mar 2022 = 6,40,000; on 31 Mar 2023 = 5,12,000. Depreciation for April–September 2023 = 5,12,000 × 20% × 6/12 = 51,200, so book value at sale = ₹4,60,800. Loss = 4,60,800 − 4,50,000 = ₹10,800. Skipping the half-year charge gives a ₹62,000 loss; charging a full year gives a ₹40,400 profit.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-7","question":"An asset costs ₹2,00,000. What is the difference between total depreciation over the first three years at 10% straight-line on cost and at 10% on the written-down value?","options":["₹6,000","₹5,800","₹4,200","₹5,420"],"answer":1,"explanation":"SLM: 20,000 × 3 = ₹60,000. WDV: 20,000 + 18,000 + 16,200 = ₹54,200. Difference = ₹5,800.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-8","question":"A machine costing ₹6,40,000 is expected to be worth ₹2,70,000 after 3 years. What written-down-value rate writes it down to exactly that amount?","options":["19.27%","20%","30%","25%"],"answer":3,"explanation":"(1 − r)³ = 2,70,000 ÷ 6,40,000 = 27/64, so 1 − r = 3/4 and r = 25%. Check: 6,40,000 → 4,80,000 → 3,60,000 → 2,70,000. 19.27% is the straight-line rate on cost, (6,40,000 − 2,70,000) ÷ 3 ÷ 6,40,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-9","question":"Machinery costing ₹6,00,000 was bought on 1 April 2021. A new machine costing ₹2,00,000 is bought on 1 October 2023, and on 1 January 2024 one of the original machines (cost ₹1,00,000) is sold. Depreciation is 10% straight-line on cost. What is the total depreciation for 2023-24 (year ending 31 March)?","options":["₹70,000","₹60,000","₹67,500","₹77,500"],"answer":2,"explanation":"Remaining old machines: 5,00,000 × 10% = ₹50,000. Machine sold: 1,00,000 × 10% × 9/12 = ₹7,500. New machine: 2,00,000 × 10% × 6/12 = ₹10,000. Total = ₹67,500. ₹77,500 charges the full ₹60,000 on the old block and then adds the sold machine again.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-10","question":"A machine costing ₹1,00,000 was bought on 1 April 2021 and is depreciated at 10% straight-line on cost (year ends 31 March). It is sold on 1 January 2024 for ₹70,000. What is the result of the sale?","options":["Loss ₹10,000","Loss ₹2,500","Neither profit nor loss","Profit ₹2,500"],"answer":1,"explanation":"Depreciation: 2021-22 ₹10,000, 2022-23 ₹10,000, 1 Apr–31 Dec 2023 ₹7,500 → accumulated ₹27,500, book value ₹72,500. Sale at ₹70,000 gives a loss of ₹2,500. Ignoring the current-year charge gives a ₹10,000 loss; charging a full year gives no profit or loss.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-11","question":"Which of these are capital expenditure? (i) Wages paid to the firm's own workers for installing a new machine (ii) Replacing the worn-out tyres of a delivery van (iii) Overhauling a second-hand truck immediately after buying it, before first use (iv) Extending the factory building to raise capacity (v) Annual maintenance contract fee","options":["(i) and (iv) only","(i), (iii) and (iv) only","(i), (ii), (iii) and (iv)","(iii) and (iv) only"],"answer":1,"explanation":"Installation wages and overhaul needed to bring a newly bought asset into use are part of its cost; an extension raises capacity. Replacing worn tyres and AMC fees only maintain the asset, so they are revenue expenditure.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-12","question":"Valuing closing stock at the lower of cost and net realisable value follows which accounting concept?","options":["Prudence (conservatism)","Matching","Going concern","Money measurement"],"answer":0,"explanation":"Prudence: provide for expected losses but do not anticipate gains, so stock is written down when its NRV falls below cost.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-13","question":"Closing stock consists of Item A (cost ₹50,000, NRV ₹60,000) and Item B (cost ₹70,000, NRV ₹45,000). At what amount should it appear in the balance sheet under Ind AS 2?","options":["₹1,05,000","₹1,20,000","₹95,000","₹1,10,000"],"answer":2,"explanation":"Ind AS 2 applies the lower of cost and NRV item by item: A at ₹50,000 (cost), B at ₹45,000 (NRV) = ₹95,000. Comparing the totals (₹1,20,000 vs ₹1,05,000) lets A's unrealised gain offset B's loss, which the standard does not allow.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-14","question":"A credit sale of ₹7,500 to Ravi was entered in the purchases book and posted from there. What is the effect on gross profit?","options":["Understated by ₹7,500","Overstated by ₹7,500","No effect","Understated by ₹15,000"],"answer":3,"explanation":"Sales are understated by ₹7,500 and purchases overstated by ₹7,500; both reduce gross profit, so it is understated by ₹15,000. (Ravi's account is also credited instead of debited, a ₹15,000 swing on his balance.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-15","question":"Goods of ₹6,000 taken by the proprietor for personal use last year were never recorded. The books for last year are closed. What entry rectifies this in the current year?","options":["Drawings A/c Dr To Purchases A/c ₹6,000","Drawings A/c Dr To Profit & Loss Adjustment A/c ₹6,000","Purchases A/c Dr To Drawings A/c ₹6,000","Capital A/c Dr To Suspense A/c ₹6,000"],"answer":1,"explanation":"Last year's purchases were overstated (profit understated). The Purchases account is closed, so the nominal-account side goes to a Profit & Loss Adjustment account: Drawings Dr, P&L Adjustment Cr ₹6,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-16","question":"Net profit before finding these errors is ₹1,50,000: (a) furniture of ₹12,000 bought at the start of the year was debited to Purchases (depreciation on furniture is 10%); (b) the sales returns book was overcast by ₹1,500; (c) rent of ₹4,000 paid was debited to the landlord's personal account. What is the corrected net profit?","options":["₹1,59,500","₹1,58,300","₹1,66,300","₹1,55,300"],"answer":1,"explanation":"(a) +12,000 for the wrong expense, −1,200 depreciation. (b) Returns were overstated, so sales were cut too much: +1,500. (c) Rent expense was missing: −4,000. 1,50,000 + 12,000 − 1,200 + 1,500 − 4,000 = ₹1,58,300.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-17","question":"Which of these normally has a credit balance in a trial balance?","options":["Drawings","Provision for doubtful debts","Discount allowed","Prepaid insurance"],"answer":1,"explanation":"A provision for doubtful debts is a credit balance deducted from debtors. Drawings, discount allowed (an expense) and prepaid insurance (an asset) are debit balances.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-18","question":"Under Ind AS 16 and Ind AS 8, how is a change from the written-down-value method to the straight-line method of depreciation treated?","options":["As a change in accounting policy, applied retrospectively","As a prior-period error, restated in comparatives","As a change in accounting estimate, applied prospectively","It is not allowed once a method has been chosen"],"answer":2,"explanation":"The depreciation method reflects the expected pattern of using up the asset's benefits, so a change in method is a change in accounting estimate and is applied prospectively from the date of change.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-19","question":"A machine bought on 1 April 2021 for ₹10,00,000 is depreciated straight-line over 10 years with nil residual value. On 1 April 2024 the remaining life is revised to 5 years and the residual value to ₹50,000. What is the depreciation for 2024-25?","options":["₹1,30,000","₹1,00,000","₹1,40,000","₹1,90,000"],"answer":0,"explanation":"Book value on 1 April 2024 = 10,00,000 − 3 × 1,00,000 = ₹7,00,000. Revised charge = (7,00,000 − 50,000) ÷ 5 = ₹1,30,000, applied prospectively. ₹1,40,000 ignores the residual value; ₹1,90,000 restarts from cost.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-20","question":"Goods costing ₹10,000 are given away as charity. What is the journal entry?","options":["Charity A/c Dr To Sales A/c","Charity A/c Dr To Purchases A/c","Purchases A/c Dr To Charity A/c","Charity A/c Dr To Cash A/c"],"answer":1,"explanation":"The goods leave at cost and were never sold, so Purchases is credited (reduced) and Charity, an expense, is debited.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-21","question":"₹19,600 is paid to a creditor in full settlement of ₹20,000. What is the correct entry?","options":["Creditor Dr ₹19,600 To Cash ₹19,600","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Allowed ₹400","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Received ₹400","Creditor Dr ₹19,600, Discount Received Dr ₹400 To Cash ₹20,000"],"answer":2,"explanation":"The whole ₹20,000 liability is cleared, ₹19,600 in cash; the ₹400 saved is a gain, credited to Discount Received.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-22","question":"Old furniture with a book value of ₹8,000 was sold for ₹6,000 and the proceeds were credited to the Sales account. By how much is the net profit overstated?","options":["₹6,000","₹2,000","₹8,000","It is understated by ₹2,000"],"answer":2,"explanation":"Reported profit includes ₹6,000 as sales. Correctly, the sale should show a loss of ₹2,000 (6,000 − 8,000). The gap is 6,000 − (−2,000) = ₹8,000 overstated; the furniture also stays in the books at ₹8,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-23","question":"A proprietor keeps incomplete records. Capital was ₹4,00,000 at the start of the year and ₹5,10,000 at the end. He withdrew ₹9,000 a month in cash and took goods worth ₹12,000 for personal use; he also introduced fresh capital of ₹50,000. What is the profit for the year?","options":["₹1,68,000","₹2,80,000","₹1,80,000","₹60,000"],"answer":2,"explanation":"Profit = closing capital − opening capital + drawings − fresh capital = 5,10,000 − 4,00,000 + (1,08,000 + 12,000) − 50,000 = ₹1,80,000. Forgetting the goods gives ₹1,68,000; adding the fresh capital gives ₹2,80,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-24","question":"An asset costing ₹2,00,000 with a residual value of ₹20,000 is depreciated straight-line at ₹36,000 a year. What useful life has been assumed?","options":["5.56 years","4.5 years","5 years","6 years"],"answer":2,"explanation":"Life = (cost − residual) ÷ annual charge = 1,80,000 ÷ 36,000 = 5 years. 5.56 years wrongly divides the full cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-25","question":"A machine costing ₹12,00,000 (residual value ₹2,00,000) is expected to run 50,000 hours. It runs 8,000 hours in year 1 and 12,000 hours in year 2. What is the year-2 charge under the units-of-production method?","options":["₹2,88,000","₹2,40,000","₹1,60,000","₹2,00,000"],"answer":1,"explanation":"Rate = (12,00,000 − 2,00,000) ÷ 50,000 = ₹20 per hour. Year 2 = 12,000 × 20 = ₹2,40,000. ₹2,88,000 ignores the residual value.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-26","question":"A firm charges 10% depreciation on the written-down value, crediting it directly to the asset account. It bought a machine for ₹5,00,000 on 1 April 2022 and another for ₹2,00,000 on 1 October 2022. What is the machinery account balance on 31 March 2024?","options":["₹5,67,000","₹5,70,000","₹5,60,000","₹5,76,000"],"answer":3,"explanation":"Machine 1: 5,00,000 × 0.9 × 0.9 = ₹4,05,000. Machine 2: half-year in 2022-23, 2,00,000 − 10,000 = 1,90,000; then 1,90,000 − 19,000 = ₹1,71,000. Total ₹5,76,000. Charging machine 2 a full first year gives ₹5,67,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-27","question":"Assertion (A): A company cannot capitalise a large advertising campaign even if it expects the campaign to bring sales for three years. Reason (R): Ind AS 38 requires spending on advertising and promotional activities to be recognised as an expense when incurred.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Ind AS 38 specifically lists advertising and promotional spending as an expense when incurred, because it does not create an identifiable intangible asset the entity controls. That is exactly why A holds.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-28","question":"Which of these costs is included in the cost of inventory under Ind AS 2?","options":["Abnormal wastage of materials","Selling and distribution costs","Freight inward on raw materials","Storage of finished goods awaiting sale"],"answer":2,"explanation":"Costs of purchase, including freight inward, are part of inventory cost. Abnormal wastage, selling costs and storage costs (unless storage is necessary in the production process) are expensed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-29","question":"Assertion (A): A revaluation decrease on an asset that carries an earlier revaluation surplus is first set off against that surplus. Reason (R): Under Ind AS 16, every revaluation decrease is recognised in profit or loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"A decrease is first debited to OCI to the extent of any surplus held for that same asset; only the excess goes to profit or loss. So A is true and R, which says 'every decrease goes to P&L', is false.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-30","question":"Which of these is a nominal account?","options":["Capital","Commission received","Debtors","Machinery"],"answer":1,"explanation":"Nominal accounts record incomes, expenses, gains and losses; commission received is an income. Capital and debtors are personal accounts and machinery is a real account.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-31","question":"The cash book shows a debit balance of ₹25,000. Cheques of ₹4,000 issued to suppliers have not yet been presented. If there is no other difference, what does the pass book show?","options":["₹29,000","₹21,000","₹25,000","₹33,000"],"answer":0,"explanation":"The cash book has already deducted the ₹4,000, but the bank has not paid it yet, so the bank balance is higher: 25,000 + 4,000 = ₹29,000.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-32","question":"The cash book shows a debit balance of ₹48,000. Cheques deposited ₹12,000 are not yet cleared; cheques issued ₹7,500 are not yet presented; bank charges ₹300 and interest credited ₹1,200 are not in the cash book; a customer paid ₹5,000 directly into the bank. What is the pass-book balance?","options":["₹58,400","₹44,400","₹46,600","₹49,400"],"answer":3,"explanation":"48,000 − 12,000 (deposits not cleared) + 7,500 (cheques not presented) − 300 + 1,200 + 5,000 = ₹49,400. Swapping the treatment of the two cheque items gives ₹58,400; missing the direct deposit gives ₹44,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-33","question":"The pass book shows an overdraft of ₹30,000. Cheques issued ₹8,000 are not yet presented, cheques deposited ₹5,000 are not yet credited, and bank charges of ₹600 appear only in the pass book. What is the cash-book balance?","options":["Overdraft ₹32,400","Overdraft ₹27,600","Overdraft ₹23,400","Overdraft ₹36,600"],"answer":0,"explanation":"Work from −30,000: the cash book has already paid the ₹8,000 (−8,000), already received the ₹5,000 (+5,000) and not yet deducted the ₹600 charges (+600): −30,000 − 8,000 + 5,000 + 600 = −32,400, an overdraft of ₹32,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-34","question":"The trial balance shows debtors ₹2,10,000, bad debts ₹4,000 and a provision for doubtful debts of ₹8,000. Adjustments: write off further bad debts of ₹10,000 and keep the provision at 5% of debtors. What is the total charge to the profit and loss account for bad and doubtful debts?","options":["₹6,000","₹12,500","₹24,000","₹16,000"],"answer":3,"explanation":"Bad debts = 4,000 + 10,000 = 14,000. New provision = 5% × (2,10,000 − 10,000) = 10,000; increase over the old ₹8,000 = 2,000. Charge = 14,000 + 2,000 = ₹16,000. ₹12,500 takes 5% on debtors before the write-off.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-35","question":"Debtors stand at ₹2,10,000. Further bad debts of ₹10,000 are written off, a 5% provision for doubtful debts is made and then a 2% provision for discount on debtors. At what net amount are debtors shown in the balance sheet?","options":["₹1,86,200","₹1,86,000","₹1,90,000","₹1,95,310"],"answer":0,"explanation":"2,10,000 − 10,000 = 2,00,000; doubtful-debt provision 10,000 → 1,90,000; discount provision 2% of the good debts 1,90,000 = 3,800 → ₹1,86,200. Taking 2% of ₹2,00,000 gives ₹1,86,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-36","question":"Wages paid during the year are ₹84,000, which includes ₹6,000 outstanding from the previous year. Wages of ₹9,000 are outstanding at the year end. What amount is charged for wages this year?","options":["₹93,000","₹81,000","₹99,000","₹87,000"],"answer":3,"explanation":"84,000 − 6,000 (belongs to last year) + 9,000 (this year's unpaid) = ₹87,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-37","question":"An annual insurance premium of ₹36,000 is paid on 1 August 2023. The accounts close on 31 March 2024. What is the prepaid insurance in the balance sheet?","options":["₹12,000","₹24,000","₹9,000","₹15,000"],"answer":0,"explanation":"The premium covers August 2023 to July 2024; April–July 2024 (4 months) lies in the next year: 36,000 × 4/12 = ₹12,000. ₹24,000 is this year's expense.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-38","question":"Net profit before the manager's commission is ₹2,20,000. The manager gets 10% of the net profit after charging his commission. What is his commission?","options":["₹20,000","₹22,000","₹24,200","₹18,000"],"answer":0,"explanation":"If commission = C, C = 10% × (2,20,000 − C), so 1.1C = 22,000 and C = ₹20,000 (= 2,20,000 × 10/110). ₹22,000 is 10% before commission.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-39","question":"Goods costing ₹50,000 are destroyed by fire and the insurer admits a claim of ₹35,000, still unpaid at the year end. Which treatment is correct?","options":["Debit P&L ₹50,000 and credit Trading ₹50,000; record the claim only when cash is received","Debit Trading ₹15,000 and make no other entry","Reduce closing stock by ₹50,000 and make no other entry","Credit Trading ₹50,000; debit Insurance Claim Receivable ₹35,000 and P&L ₹15,000"],"answer":3,"explanation":"The goods are taken out of Trading at cost (credit ₹50,000). The admitted claim is an asset (receivable ₹35,000) even though unpaid, and only the uncovered ₹15,000 is a loss in the P&L. Waiting for cash breaks the accrual concept.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-40","question":"Opening stock ₹60,000, purchases ₹3,40,000, purchase returns ₹10,000, carriage inward ₹15,000, wages ₹25,000, sales ₹5,00,000, sales returns ₹20,000, closing stock ₹80,000. What is the gross profit?","options":["₹1,50,000","₹1,70,000","₹1,20,000","₹1,30,000"],"answer":3,"explanation":"Net sales 4,80,000. Cost of goods sold = 60,000 + 3,30,000 + 15,000 + 25,000 − 80,000 = 3,50,000. Gross profit = ₹1,30,000. Forgetting sales returns gives ₹1,50,000; forgetting purchase returns gives ₹1,20,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-41","question":"Closing stock of ₹80,000 appears inside the trial balance (purchases have already been adjusted for it). Where is it shown in the final accounts?","options":["Only in the balance sheet, as a current asset","On the credit side of the Trading account and in the balance sheet","Only on the credit side of the Trading account","On the debit side of the Trading account"],"answer":0,"explanation":"When closing stock is inside the trial balance, it has already been deducted from purchases (adjusted purchases). Crediting Trading again would count it twice, so it goes only to the balance sheet.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-42","question":"Goods worth ₹12,000 received on the last day of the year are included in closing stock, but the supplier's invoice has not been recorded. What is the effect?","options":["Profit overstated by ₹12,000 and creditors understated by ₹12,000","No effect on profit, because the goods are in stock","Profit understated by ₹12,000","Profit overstated by ₹24,000"],"answer":0,"explanation":"The goods raise closing stock (and profit) by ₹12,000, but the matching purchase is missing. Recording the purchase raises cost of goods sold by ₹12,000 and creates the creditor, so profit was overstated by ₹12,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-43","question":"A trader prices goods at cost plus 20%. Goods sent on approval at ₹24,000 (selling price) were recorded as sales, but the customer has not yet approved them at the year end. What adjustment to profit is needed?","options":["Reduce profit by ₹24,000","Reduce profit by ₹4,800","Increase profit by ₹20,000","Reduce profit by ₹4,000"],"answer":3,"explanation":"Cancel the sale (−24,000) and bring the goods back into closing stock at cost, 24,000 ÷ 1.2 = 20,000 (+20,000). Net reduction = ₹4,000, the profit loaded in the price. 20% of 24,000 (₹4,800) confuses mark-up on cost with margin on sales.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-44","question":"The cash book shows an overdraft of ₹15,000. A cheque of ₹2,000 issued to a supplier was entered twice on the payments side, cheques deposited ₹6,000 are not yet credited, and interest on overdraft ₹900 has been charged only by the bank. What is the pass-book balance?","options":["Overdraft ₹23,900","Overdraft ₹21,900","Overdraft ₹8,100","Overdraft ₹19,900"],"answer":3,"explanation":"Start at −15,000. The duplicate entry overstated payments, so the true position is better: +2,000 → −13,000. Deposits not credited: −6,000 → −19,000. Interest: −900 → −19,900, an overdraft of ₹19,900.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-45","question":"₹1,00,000 is invested in 12% debentures. Interest for only 9 months has been received during the year. What accrued interest is shown at the year end?","options":["₹3,000","₹9,000","₹12,000","₹4,000"],"answer":0,"explanation":"Annual interest = ₹12,000; 9 months (₹9,000) received, so 3 months = ₹3,000 has accrued.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-46","question":"Which item appears on the credit side of the Trading account?","options":["Closing stock","Carriage inward","Wages","Opening stock"],"answer":0,"explanation":"Closing stock (when it is outside the trial balance) is credited to Trading; carriage inward, wages and opening stock are debits.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-47","question":"Opening debtors ₹40,000, closing debtors ₹55,000, cash received from debtors ₹2,60,000, discount allowed ₹5,000, bad debts ₹3,000 and sales returns ₹7,000. What were the credit sales?","options":["₹2,75,000","₹2,80,000","₹2,60,000","₹2,90,000"],"answer":3,"explanation":"Debtors account: credit sales = closing 55,000 + cash 2,60,000 + discount 5,000 + bad debts 3,000 + returns 7,000 − opening 40,000 = ₹2,90,000. Ignoring the three non-cash credits gives ₹2,75,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-48","question":"Opening creditors ₹30,000, closing creditors ₹45,000, cash paid to creditors ₹1,80,000, discount received ₹4,000, purchase returns ₹6,000 and cash purchases ₹20,000. What are the total purchases before deducting returns?","options":["₹2,25,000","₹2,05,000","₹2,19,000","₹2,15,000"],"answer":0,"explanation":"Credit purchases = 45,000 + 1,80,000 + 4,000 + 6,000 − 30,000 = 2,05,000. Total purchases = 2,05,000 + 20,000 cash = ₹2,25,000. ₹2,19,000 is net of returns; ₹2,05,000 forgets the cash purchases.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-49","question":"Sales are ₹6,00,000, opening stock ₹70,000 and purchases ₹4,80,000. Gross profit is 25% of cost. What is the closing stock?","options":["₹1,00,000","₹1,20,000","₹50,000","₹70,000"],"answer":3,"explanation":"Profit is 25% of cost, so cost of goods sold = 6,00,000 ÷ 1.25 = 4,80,000. Closing stock = 70,000 + 4,80,000 − 4,80,000 = ₹70,000. Treating 25% as a margin on sales gives ₹1,00,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-50","question":"A fire destroys stock. Stock on 1 April was ₹80,000; purchases to the date of the fire ₹3,20,000; sales ₹4,50,000; gross profit is 20% of sales. Goods worth ₹10,000 were saved. The stock was insured for ₹24,000 under a policy with an average clause. What is the claim?","options":["₹18,000","₹24,000","₹30,000","₹14,400"],"answer":0,"explanation":"Stock at fire = 80,000 + 3,20,000 − (4,50,000 × 80%) = ₹40,000. Loss = 40,000 − 10,000 = ₹30,000. Under-insured, so claim = 30,000 × 24,000/40,000 = ₹18,000. Using 20% on cost gives ₹14,400.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-51","question":"Which year-end transaction affects only the balance sheet, not the profit for the year?","options":["Salaries outstanding","Depreciation on machinery","Commission accrued but not received","Machinery bought for cash on the last day of the year"],"answer":3,"explanation":"Buying an asset for cash swaps one asset for another; no expense arises in this year. The other three are adjustments that change the P&L as well.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-52","question":"The trial balance shows Rent ₹22,000 and, separately, Outstanding Rent ₹2,000 (credit). Among the adjustments it is also noted that rent of ₹2,000 is outstanding. What amount of rent goes to the profit and loss account?","options":["₹22,000","₹24,000","₹20,000","₹26,000"],"answer":0,"explanation":"An item that already appears in the trial balance has been recorded; the note simply describes it. The ₹22,000 already includes the outstanding ₹2,000, so adding it again (₹24,000) double-counts.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-53","question":"Profit before adjustments is ₹3,00,000. Adjustments: closing stock ₹50,000 not yet recorded; salary outstanding ₹8,000; rent prepaid ₹3,000; depreciation 10% on machinery of ₹2,00,000; commission accrued ₹2,500; further bad debts ₹1,500. What is the adjusted profit?","options":["₹3,36,000","₹2,76,000","₹3,46,000","₹3,26,000"],"answer":3,"explanation":"3,00,000 + 50,000 − 8,000 + 3,000 − 20,000 + 2,500 − 1,500 = ₹3,26,000. Reversing outstanding and prepaid gives ₹3,36,000; forgetting depreciation gives ₹3,46,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-54","question":"With the cash book and pass book both showing favourable balances, which item makes the pass-book balance higher than the cash-book balance?","options":["Cheques issued but not yet presented for payment","Cheques deposited but not yet cleared","Bank charges debited only in the pass book","A customer's cheque dishonoured, not yet recorded in the cash book"],"answer":0,"explanation":"The cash book has deducted the cheques issued, but the bank has not paid them yet, so the bank's figure is higher. The other three make the pass book lower.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-55","question":"Assertion (A): An error made by the bank in the pass book needs no entry in the cash book. Reason (R): The cash book is corrected only for items the business itself has not recorded or has recorded wrongly.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A bank error is corrected by the bank; it appears only as a reconciling item in the BRS. The cash book is amended only for the business's own omissions and errors, which is why no entry is needed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-56","question":"The cash book shows a debit balance of ₹36,000 and the pass book ₹43,250. Cheques issued ₹15,000 are not presented; cheques deposited ₹9,000 are not cleared; bank charges ₹250 and a dividend of ₹3,000 collected by the bank are not in the cash book; a customer's cheque of ₹1,500, deposited and later dishonoured, has not been recorded as dishonoured in the cash book. What is the corrected cash-book balance?","options":["₹43,250","₹38,750","₹40,250","₹37,250"],"answer":3,"explanation":"Correct the cash book only for its own omissions: 36,000 − 250 + 3,000 − 1,500 = ₹37,250. Check: 37,250 − 9,000 + 15,000 = 43,250, the pass-book figure. Treating the dishonour as an addition gives ₹40,250.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-57","question":"A sole trader charges interest on capital at 10% on capital of ₹5,00,000. How many of these statements are true? (1) Net profit falls by ₹50,000. (2) The closing capital is unchanged by the entry. (3) Interest on drawings, if charged, would increase net profit. (4) The entry causes a cash outflow of ₹50,000.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) True: the interest is debited to P&L. (2) True: the same ₹50,000 is credited to capital, offsetting the lower profit. (3) True: interest on drawings is credited to P&L. (4) False: nothing is paid out; it is a book entry. Three are true.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-58","question":"Goods worth ₹5,000 are lost in transit and the carrier accepts a claim of ₹3,000, not yet received. How much is debited to the profit and loss account?","options":["₹5,000","₹3,000","Nil","₹2,000"],"answer":3,"explanation":"The goods are removed from Trading (₹5,000); ₹3,000 is a receivable from the carrier and only the uncovered ₹2,000 is a loss.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-59","question":"Carriage outward (on goods sold) is debited to:","options":["Trading account","Profit and loss account","Balance sheet","Capital account"],"answer":1,"explanation":"Carriage outward is a selling and distribution expense, so it goes to the P&L. Carriage inward is part of the cost of goods and goes to Trading.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-60","question":"Opening stock ₹1,20,000, purchases ₹6,00,000 and sales ₹7,50,000. Goods are sold at cost plus 25%. The owner took goods costing ₹20,000 for personal use, which were not recorded. What should the closing stock be?","options":["₹1,00,000","₹1,20,000","₹1,37,500","₹80,000"],"answer":0,"explanation":"Cost of goods sold = 7,50,000 ÷ 1.25 = 6,00,000. Closing stock = 1,20,000 + 6,00,000 − 20,000 (drawings) − 6,00,000 = ₹1,00,000. Ignoring the goods taken gives ₹1,20,000; using 25% of sales gives ₹1,37,500.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-61","question":"A and B share profits 3 : 2. C is admitted and the new ratio of A, B and C is 5 : 3 : 2. What is the sacrificing ratio of A and B?","options":["3 : 2","1 : 1","5 : 3","2 : 1"],"answer":1,"explanation":"A: 3/5 − 5/10 = 1/10. B: 2/5 − 3/10 = 1/10. Sacrificing ratio 1 : 1, not the old ratio.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-62","question":"A and B share profits 5 : 3. C is admitted for a 1/4 share, which he takes equally from A and B. What is the new ratio of A, B and C?","options":["15 : 9 : 8","5 : 3 : 2","2 : 1 : 1","4 : 3 : 1"],"answer":2,"explanation":"Each gives 1/8. A = 5/8 − 1/8 = 4/8; B = 3/8 − 1/8 = 2/8; C = 2/8 → 2 : 1 : 1. 15 : 9 : 8 is what you get if C takes his share from A and B in their old ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-63","question":"A firm's capital employed is ₹10,00,000 and the normal rate of return is 12%. Its average profit is ₹1,80,000. What is goodwill at three years' purchase of super profit?","options":["₹5,40,000","₹1,80,000","₹5,00,000","₹3,60,000"],"answer":1,"explanation":"Normal profit = 12% × 10,00,000 = 1,20,000. Super profit = 1,80,000 − 1,20,000 = 60,000. Goodwill = 60,000 × 3 = ₹1,80,000. ₹5,40,000 multiplies the whole average profit; ₹5,00,000 capitalises the super profit instead.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-64","question":"A firm earns an average profit of ₹1,50,000; the normal rate of return is 10%. Its assets are ₹18,00,000 and outside liabilities ₹5,00,000. What is goodwill by capitalising the average profit?","options":["₹15,00,000","Nil","₹2,00,000","₹1,50,000"],"answer":2,"explanation":"Capitalised value = 1,50,000 ÷ 10% = 15,00,000. Net assets = 18,00,000 − 5,00,000 = 13,00,000. Goodwill = 15,00,000 − 13,00,000 = ₹2,00,000. Comparing with total assets (ignoring liabilities) would wrongly show no goodwill.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-65","question":"A and B have capitals of ₹3,00,000 and ₹2,00,000 after all adjustments. C is admitted for a 1/4 share and brings ₹2,00,000 as capital, but nothing for goodwill. What is the hidden goodwill of the firm?","options":["₹3,00,000","₹1,00,000","₹25,000","₹75,000"],"answer":1,"explanation":"C's ₹2,00,000 for 1/4 implies total capital of ₹8,00,000. Actual capital including C = 3,00,000 + 2,00,000 + 2,00,000 = ₹7,00,000. Hidden goodwill = ₹1,00,000 (C's share of it ₹25,000). ₹3,00,000 forgets to include C's own capital.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-66","question":"A and B share profits 3 : 2. C is admitted for a 1/5 share and pays ₹50,000 as premium for goodwill. The new ratio is A 2 : B 2 : C 1. How is the premium shared?","options":["A ₹30,000 and B ₹20,000","A ₹50,000 and B nil","A ₹25,000 and B ₹25,000","A ₹40,000 and B ₹10,000"],"answer":1,"explanation":"Premium goes to the partners who sacrifice, in the sacrificing ratio. A: 3/5 − 2/5 = 1/5; B: 2/5 − 2/5 = 0. Only A sacrifices, so A gets all ₹50,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-67","question":"On admitting a partner, the firm revalues: building (book value ₹5,00,000) up by 10%; stock down by ₹15,000; a 5% provision is created on debtors of ₹1,00,000; an unrecorded liability of ₹8,000 is brought in; creditors of ₹2,000 are found not payable. What is the profit on revaluation?","options":["₹20,000","₹40,000","₹24,000","₹29,000"],"answer":2,"explanation":"+50,000 (building) − 15,000 (stock) − 5,000 (provision) − 8,000 (new liability) + 2,000 (creditors written back) = ₹24,000, shared by the old partners in the old ratio. Treating the creditor write-back as a loss gives ₹20,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-68","question":"The partnership deed is silent on all financial matters. Under the Indian Partnership Act, 1932, which of these is allowed?","options":["Interest on capital at 6% a year","Interest at 6% a year on a loan given by a partner to the firm","A salary to the working partner","Sharing profits in the ratio of capitals"],"answer":1,"explanation":"Without agreement, profits are shared equally, there is no interest on capital and no salary, but a partner's loan to the firm carries interest at 6% a year.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-69","question":"Profit for the year is ₹1,20,000. A's capital is ₹4,00,000 and B's ₹2,00,000. Interest on capital is 10%, B gets a salary of ₹2,000 a month, and the remaining profit is shared 3 : 2. What is B's total share?","options":["₹62,000","₹58,400","₹45,200","₹61,600"],"answer":1,"explanation":"Interest: A 40,000, B 20,000. B's salary 24,000. Divisible = 1,20,000 − 60,000 − 24,000 = 36,000; B's 2/5 = 14,400. B total = 20,000 + 24,000 + 14,400 = ₹58,400. ₹61,600 is A's total; ₹62,000 splits the balance equally.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-70","question":"A, B and C share profits 2 : 2 : 1. C is guaranteed a minimum profit of ₹30,000, any shortfall to be borne by A and B in the ratio 3 : 2. The firm's profit is ₹1,00,000. What is A's final share?","options":["₹40,000","₹35,000","₹34,000","₹30,000"],"answer":2,"explanation":"C's normal share = 20,000; shortfall 10,000. A bears 3/5 = 6,000, so A gets 40,000 − 6,000 = ₹34,000 (B gets 36,000). ₹35,000 shares the shortfall equally.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-71","question":"A partner withdraws ₹5,000 at the beginning of every month for 12 months. Interest on drawings is 12% a year. What is the interest on drawings?","options":["₹3,600","₹3,900","₹3,300","₹7,200"],"answer":1,"explanation":"Total ₹60,000; drawings at the start of each month are outstanding for 6.5 months on average: 60,000 × 12% × 6.5/12 = ₹3,900. End-of-month drawings would give 5.5 months (₹3,300) and mid-month 6 months (₹3,600).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-72","question":"A partner withdraws ₹15,000 at the beginning of each quarter. Interest on drawings is 10% a year. What is the interest on drawings for the year?","options":["₹2,250","₹3,000","₹3,750","₹6,000"],"answer":2,"explanation":"Total ₹60,000. Average period for start-of-quarter drawings = (12 + 9 + 6 + 3) ÷ 4 = 7.5 months: 60,000 × 10% × 7.5/12 = ₹3,750. End-of-quarter drawings would give 4.5 months (₹2,250).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-73","question":"A, B and C share profits 4 : 3 : 2. B retires, and A and C take over his share in the ratio 1 : 2. What is the new ratio of A and C?","options":["2 : 1","5 : 4","1 : 2","4 : 3"],"answer":1,"explanation":"B's 3/9 is split 1 : 2: A gains 1/9 and C 2/9. A = 4/9 + 1/9 = 5/9; C = 2/9 + 2/9 = 4/9 → 5 : 4. 1 : 2 is only the gaining ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-74","question":"A, B and C share profits 3 : 2 : 1. C retires; A and B continue in the ratio 3 : 2. Goodwill is valued at ₹1,80,000 and is not to appear in the books. How much does A's capital account contribute to C's share of goodwill?","options":["₹15,000","₹30,000","₹18,000","₹90,000"],"answer":2,"explanation":"C's share = 1,80,000 × 1/6 = 30,000. Gains: A 3/5 − 3/6 = 3/30, B 2/5 − 2/6 = 2/30, so gaining ratio 3 : 2. A pays 30,000 × 3/5 = ₹18,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-75","question":"A and B share profits equally and decide to share 3 : 2 in future. Goodwill is valued at ₹60,000 and is not to be shown in the books. What entry is passed?","options":["B's capital Dr ₹6,000 To A's capital ₹6,000","A's capital Dr ₹6,000 To B's capital ₹6,000","A's capital Dr ₹36,000 To B's capital ₹36,000","No entry is needed for a change in ratio"],"answer":1,"explanation":"A gains 3/5 − 1/2 = 1/10 and B sacrifices 1/10. The gainer compensates the sacrificer: 60,000 × 1/10 = ₹6,000, debited to A and credited to B.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-76","question":"A, B and C share profits 2 : 2 : 1. C dies on 30 June. His share of profit up to death is based on the average of the last three years' profits: ₹1,80,000, ₹2,10,000 and ₹2,70,000. The year starts on 1 April. What is C's share of profit?","options":["₹13,500","₹11,000","₹44,000","₹22,000"],"answer":1,"explanation":"Average profit = 6,60,000 ÷ 3 = 2,20,000. April to June = 3 months: 2,20,000 × 3/12 × 1/5 = ₹11,000. Using only last year's ₹2,70,000 gives ₹13,500; using six months gives ₹22,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-77","question":"Under the fixed capital method, where are the partners' interest on capital, salary and share of profit credited?","options":["To their capital accounts","To the profit and loss account","To their current accounts","To the revaluation account"],"answer":2,"explanation":"With fixed capitals, the capital accounts carry only the agreed capital (and permanent additions or withdrawals); all routine items such as interest, salary, drawings and profit share go through current accounts.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-78","question":"On dissolution, assets (other than cash) with a book value of ₹5,00,000 realise ₹4,40,000. Creditors of ₹1,20,000 accept ₹1,15,000 in full settlement, and realisation expenses of ₹6,000 are paid by the firm. What is the loss on realisation?","options":["₹66,000","₹55,000","₹61,000","₹60,000"],"answer":2,"explanation":"Loss on assets 60,000 − gain on creditors 5,000 + expenses 6,000 = ₹61,000. Treating the creditors' discount as a loss gives ₹66,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-79","question":"After all adjustments, A's capital is ₹4,50,000 and B's ₹3,00,000. C is admitted for a 1/4 share and must bring capital equal to 1/4 of the total capital of the new firm. How much does C bring?","options":["₹1,87,500","₹2,50,000","₹3,00,000","₹2,00,000"],"answer":1,"explanation":"Old partners' ₹7,50,000 is 3/4 of the new total, so total = 10,00,000 and C brings ₹2,50,000. ₹1,87,500 is 1/4 of the old capital, not of the new total.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-80","question":"A and B share profits 3 : 2 and have capitals of ₹3,00,000 and ₹2,20,000. C is admitted for 1/5 and brings ₹1,20,000. A and B keep their ratio between themselves and agree to adjust their capitals on the basis of C's capital, in the new profit-sharing ratio. What adjustment does A make?","options":["A brings in ₹12,000","A withdraws ₹12,000","A withdraws ₹1,20,000","A brings in ₹48,000"],"answer":1,"explanation":"Total capital implied by C = 1,20,000 × 5 = 6,00,000. New ratio: A 3/5 × 4/5 = 12/25, B 8/25, C 5/25. A's capital should be 6,00,000 × 12/25 = 2,88,000, so A withdraws 3,00,000 − 2,88,000 = ₹12,000 (B, whose capital should be ₹1,92,000, withdraws ₹28,000).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-81","question":"The partnership deed allows interest on capital: A ₹24,000 and B ₹16,000. The firm's profit is only ₹30,000. Interest on capital is treated as an appropriation of profit. How is the profit distributed?","options":["A ₹24,000 and B ₹16,000, and the ₹10,000 shortfall is shared as a loss","A ₹15,000 and B ₹15,000","A ₹18,000 and B ₹12,000","A ₹24,000 and B ₹6,000"],"answer":2,"explanation":"As an appropriation, interest on capital cannot exceed the available profit; the ₹30,000 is shared in the ratio of the interest, 24 : 16 = 3 : 2, giving A ₹18,000 and B ₹12,000. (If interest were a charge, it would be allowed in full and create a loss.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-82","question":"When the partnership deed is silent, which of these rules apply under the Indian Partnership Act, 1932? (1) Profits and losses are shared equally (2) No interest on capital (3) Interest at 6% a year on partners' loans (4) No salary or commission to any partner","options":["(1) and (2) only","(1), (2) and (3) only","(1), (2), (3) and (4)","(2) and (4) only"],"answer":2,"explanation":"All four are the default rules of Section 13 when the partners have not agreed otherwise.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-83","question":"Goodwill is to be valued at two years' purchase of the weighted average profit of the last three years, weighted 1, 2 and 3 (latest year highest). Profits were ₹1,00,000, ₹1,20,000 and ₹1,50,000; the latest year's profit includes a non-recurring gain of ₹30,000. What is goodwill?","options":["₹2,63,333","₹2,33,333","₹2,26,667","₹1,16,667"],"answer":1,"explanation":"Normalised latest profit = 1,20,000. Weighted average = (1,00,000 × 1 + 1,20,000 × 2 + 1,20,000 × 3) ÷ 6 = 7,00,000 ÷ 6 = 1,16,667. Goodwill = 2 × 1,16,667 = ₹2,33,333. Keeping the non-recurring gain gives ₹2,63,333.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-84","question":"On admitting a partner, the partners want the assets and liabilities to stay at their old book values even though some have been revalued. What do they use?","options":["A revaluation account, closed to the new ratio","A realisation account","A memorandum revaluation account","A goodwill account"],"answer":2,"explanation":"A memorandum revaluation account records the net gain or loss, credited to the old partners in the old ratio, and then reverses it among all partners in the new ratio, so the book values stay unchanged.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-85","question":"Goodwill of ₹40,000 already stands in the books when a new partner is admitted. What happens to it?","options":["It is carried forward unchanged","It is written off among the old partners in the old ratio","It is written off among all partners in the new ratio","It is credited to the new partner"],"answer":1,"explanation":"Existing goodwill belongs to the old partners and is written off to their capital accounts in the old ratio before the new partner's goodwill is dealt with.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-86","question":"A, B and C share profits 2 : 2 : 1. C retires. The balance sheet shows a general reserve of ₹60,000 and a debit balance of ₹15,000 in the profit and loss account. What net amount is credited to C's capital for these two items?","options":["₹12,000","₹9,000","₹15,000","₹3,000"],"answer":1,"explanation":"Both items are distributed in the old ratio: (60,000 − 15,000) × 1/5 = ₹9,000. ₹12,000 forgets the accumulated loss.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-87","question":"A partner's closing capital is ₹2,30,000 under the fluctuating capital method. During the year his drawings were ₹30,000 and his share of profit ₹40,000. Interest on capital at 10% a year on opening capital has been credited to his capital account. What was the interest on capital?","options":["₹23,000","₹20,000","₹22,000","₹26,000"],"answer":1,"explanation":"Closing = opening × 1.10 + 40,000 − 30,000, so 1.1 × opening = 2,20,000 and opening = 2,00,000. Interest = ₹20,000. ₹22,000 forgets that the interest itself sits inside the closing balance.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-88","question":"The document setting out the terms agreed among partners is called the:","options":["Memorandum of association","Prospectus","Partnership deed (articles of partnership)","Certificate of incorporation"],"answer":2,"explanation":"A partnership deed, also called articles of partnership, records capital, profit ratio, interest, salaries and other terms. The others relate to companies.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-89","question":"A new partner pays the old partners their share of goodwill privately, outside the firm. What entry is made in the firm's books?","options":["Cash Dr To Premium for Goodwill","No entry","Goodwill A/c Dr To Old partners' capitals","New partner's capital Dr To Old partners' capitals"],"answer":1,"explanation":"The payment does not pass through the firm, so the firm's books record nothing for it.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-90","question":"A, B and C share profits 5 : 3 : 2. D is admitted for 1/5, taking 1/10 from A and the rest equally from B and C. What is the new ratio of A, B, C and D?","options":["9 : 5 : 2 : 4","8 : 6 : 2 : 4","8 : 5 : 3 : 4","20 : 12 : 8 : 10"],"answer":2,"explanation":"A gives 1/10; B and C give 1/20 each. A = 5/10 − 1/10 = 8/20; B = 6/20 − 1/20 = 5/20; C = 4/20 − 1/20 = 3/20; D = 4/20 → 8 : 5 : 3 : 4. 20 : 12 : 8 : 10 assumes everyone gives in the old ratio.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
];

export default questions;
